package com.example.starter.domain;

/**
 * 停电事件状态。
 */
public enum OutageStatus {

    /** 停电中。 */
    ACTIVE,
    /** 市电已恢复。 */
    RESTORED
}

package com.example.starter.domain;

/**
 * 调度单状态。
 */
public enum OrderStatus {

    /** 已生成待派单（内部瞬态，正常流程内立即完成油机分配）。 */
    PENDING,
    /** 油机已分配、在途未确认。 */
    DISPATCHED,
    /** 油机到位并回传发电确认。 */
    GENERATING,
    /** 发电确认超时（派单后 30 分钟恰满仍未确认）升级的异常态，允许改派。 */
    GENERATION_ABNORMAL,
    /** 市电恢复，调度单解除并释放油机（终态）。 */
    RELEASED,
    /** 调度单结案（终态）。 */
    CLOSED
}

package com.example.starter.domain;

/**
 * 油机服务状态。
 */
public enum GeneratorStatus {

    /** 空闲可派。 */
    IDLE,
    /** 已派单、在途。 */
    DISPATCHED,
    /** 发电中。 */
    GENERATING
}

package com.example.starter.support;

import java.time.Instant;

/**
 * 可控时钟：生产环境返回系统 UTC 时刻，测试中可固定或拨动，保证超时与并发断言确定性。
 */
public interface Clock {

    /** 当前时刻（UTC）。 */
    Instant now();
}

package com.example.starter.support;

import org.springframework.stereotype.Component;

import java.time.Instant;

/**
 * 生产环境时钟，直接读取系统时间。
 */
@Component
public class SystemClock implements Clock {

    @Override
    public Instant now() {
        return Instant.now();
    }
}

